void fft_transform(int a[], int n, int p, bool invert) {
    int logn = __lg(n);
    for (int i = 0; i < logn; i++) {
        for (int mask = 0; mask < n; mask++) {
            if (mask & (1 << i)) {
                int prev_mask = mask ^ (1 << i);
                if (!invert) {
                    a[mask] = (a[mask] + a[prev_mask]) % p;
                } else {
                    a[mask] = (a[mask] - a[prev_mask] + p) % p;
                }
            }
        }
    }
}

vector<int> convolution_power(const vector<int>& a, int k, int p) {
    int n = (int)a.size();
    if (k == 1) return a;
    if (k % 2 == 1) {
        vector<int> prev = convolution_power(a, k - 1, p);
        vector<int> result(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                result[i + j] = (result[i + j] + (long long)prev[i] * a[j]) % p;
            }
        }
        return result;
    } else {
        vector<int> half = convolution_power(a, k / 2, p);
        vector<int> result(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                result[i + j] = (result[i + j] + (long long)half[i] * half[j]) % p;
            }
        }
        return result;
    }
}

vector<int> subset_power(const vector<int>& a, int k, int p) {
    const int LOGN = 19;
    static int fa[LOGN][1 << LOGN], fc[LOGN][1 << LOGN];
    int n = a.size();
    while (n & (n - 1)) n++;
    for (int i = 0; i < LOGN; i++) {
        for (int j = 0; j < n; j++) {
            fa[i][j] = (i == __builtin_popcount(j)) ? (j < (int)a.size() ? a[j] : 0) : 0;
        }
        fft_transform(fa[i], n, p, false);
    }
    vector<int> res(n, 0);
    for (int i = 0; i < n; i++) {
        vector<int> v(LOGN);
        for (int j = 0; j < LOGN; j++) v[j] = fa[j][i];
        v = convolution_power(v, k, p);
        for (int j = 0; j < LOGN; j++) fc[j][i] = v[j];
    }
    for (int i = 0; i < LOGN; i++) {
        fft_transform(fc[i], n, p, true);
        for (int j = 0; j < n; j++) {
            if (__builtin_popcount(j) == i) {
                res[j] = fc[i][j];
            }
        }
    }
    return res;
}

